%% |prepared context is the first max_chunks results at or above the floor| — laws/prompt_context.lawspec:282
%% Over results that all have a relevance score, prepare_context/2 returns
%%     the results whose score is at or above min_relevance, in input order, cut
%%     to the first max_chunks of them and numbered from 1. A score exactly at
%%     the floor passes. The floor applies before the ceiling, so a result below
%%     the floor never takes a place from one that passes.
%% for all (maxChunks :: BigUInt) (floor :: Integer) (rs :: List (cake.laws.prompt_context::type::ScoredResult)) => prepareContext maxChunks floor (scoredOnly rs) = preparedOf maxChunks floor (scoredOnly rs) end for all
law_prepared_context_is_the_first_max_chunks_results(Schema, Symbols, [MaxChunks, Floor, Rs]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:prepare_context(
            Schema,
            Symbols,
            MaxChunks,
            Floor,
            lawspec_definitions:scored_only(Schema, Symbols, Rs)
        ),
        lawspec_definitions:prepared_of(
            Schema,
            Symbols,
            MaxChunks,
            Floor,
            lawspec_definitions:scored_only(Schema, Symbols, Rs)
        ),
        ?LAW_PREPARED_CONTEXT_IS_THE_FIRST_MAX_CHUNKS_RESULTS
    ).

