%% |a result with no relevance score never passes the floor| — laws/prompt_context.lawspec:361
%% prepare_context/2 treats a result with no relevance score as if it were
%%     not there: the output is what the scored results alone would give,
%%     whatever the floor, a floor of zero included. No score is not a score of
%%     zero.
%% for all (maxChunks :: BigUInt) (floor :: Integer) (rs :: List (cake.laws.prompt_context::type::ScoredResult)) => prepareContext maxChunks floor rs = prepareContext maxChunks floor (scoredOnly rs) end for all
law_a_result_with_no_relevance_score_never_passes(Schema, Symbols, [MaxChunks, Floor, Rs]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:prepare_context(Schema, Symbols, MaxChunks, Floor, Rs),
        lawspec_definitions:prepare_context(
            Schema,
            Symbols,
            MaxChunks,
            Floor,
            lawspec_definitions:scored_only(Schema, Symbols, Rs)
