-define(LAW_WITH_NO_OPTIONS_THE_CEILING_IS_TEN_CHUNKS_AND,
    <<"cake.laws.prompt_context::|with no options the ceiling is ten chunks and the floor is 0.30|">>
).

%% |with no options the ceiling is ten chunks and the floor is 0.30| — laws/prompt_context.lawspec:415
%% prepare_context/2 with no options is prepare_context/2 with max_chunks
%%     10 and min_relevance 0.3. Generated lists are short, so the law repeats
%%     the results up to four times over to take them past ten.
%% for all (rs :: List (cake.laws.prompt_context::type::ScoredResult)) (times :: BigUInt) => prepareContextByDefault (manyOf rs (((times rem 5) :: BigUInt))) = prepareContext 10 30 (manyOf rs (((times rem 5) :: BigUInt))) end for all
law_with_no_options_the_ceiling_is_ten_chunks_and(Schema, Symbols, [Rs, Times]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:prepare_context_by_default(
            Schema,
            Symbols,
            lawspec_definitions:many_of(
                Schema,
                Symbols,
                Rs,
                lawspec_beam_schema:validate(
                    lawspec_beam_scalar:convert(
                        lawspec_beam_scalar:remainder(Times, 5, <<"BigUInt">>, <<"Integer">>),
                        type_big_u_int(),
                        64
                    ),
                    type_big_u_int(),
                    Schema
                )
            )
        ),
        lawspec_definitions:prepare_context(
            Schema,
            Symbols,
            10,
            30,
            lawspec_definitions:many_of(
                Schema,
                Symbols,
                Rs,
                lawspec_beam_schema:validate(
                    lawspec_beam_scalar:convert(
                        lawspec_beam_scalar:remainder(Times, 5, <<"BigUInt">>, <<"Integer">>),
                        type_big_u_int(),
                        64
                    ),
                    type_big_u_int(),
                    Schema
                )
            )
        ),
        ?LAW_WITH_NO_OPTIONS_THE_CEILING_IS_TEN_CHUNKS_AND
    ).

