%% |a formatted chunk is its index in brackets, then its prompt context| — laws/prompt_context.lawspec:442
%% format_chunk/1 renders an indexed chunk as `[N] ` followed by the
%%     retrieval unit's Cake.Promptable prompt context, verbatim.
%% for all (index :: BigUInt) (r :: cake.laws.prompt_context::type::ScoredResult) => formatChunk (((index + 1) :: BigUInt)) r = entryOf (((index + 1) :: BigUInt)) r end for all
law_a_formatted_chunk_is_its_index_in_brackets_then(Schema, Symbols, [Index, R]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:format_chunk(
            Schema,
            Symbols,
            lawspec_beam_schema:validate(
                lawspec_beam_scalar:convert((Index + 1), type_big_u_int(), 64),
                type_big_u_int(),
                Schema
