-define(LAW_HISTORY_IS_THE_LAST_FIVE_COMPLETE_EXCHANGES,
    <<"cake.laws.prompt_context::|history is the last five complete exchanges, oldest first|">>
).

%% |history is the last five complete exchanges, oldest first| — laws/prompt_context.lawspec:464
%% history_messages/1 turns the flat question, answer, question, answer
%%     history into alternating user and assistant messages, keeps only the last
%%     five exchanges, and drops a last question that has no answer. So it
%%     always returns an even number of messages, and at most ten. Generated
%%     lists are short, so the law repeats the history up to five times over to
%%     take it past five exchanges.
%% for all (history :: List (Text)) (times :: BigUInt) => historyMessages (historyTimes history (((times rem 6) :: BigUInt))) = recentExchanges (historyTimes history (((times rem 6) :: BigUInt))) and (Length(historyMessages (historyTimes history (((times rem 6) :: BigUInt)))) rem 2) = 0 and (Length(historyMessages (historyTimes history (((times rem 6) :: BigUInt)))) <= 10) = true end for all
law_history_is_the_last_five_complete_exchanges(Schema, Symbols, [History, Times]) ->
    ((lawspec_beam_runtime:assert_equal(
        lawspec_definitions:history_messages(
            Schema,
            Symbols,
            lawspec_definitions:history_times(
                Schema,
                Symbols,
                History,
                lawspec_beam_schema:validate(
                    lawspec_beam_scalar:convert(
                        lawspec_beam_scalar:remainder(Times, 6, <<"BigUInt">>, <<"Integer">>),
                        type_big_u_int(),
                        64
                    ),
                    type_big_u_int(),
                    Schema
                )
            )
        ),
        lawspec_definitions:recent_exchanges(
            Schema,
            Symbols,
            lawspec_definitions:history_times(
                Schema,
                Symbols,
                History,
                lawspec_beam_schema:validate(
                    lawspec_beam_scalar:convert(
                        lawspec_beam_scalar:remainder(Times, 6, <<"BigUInt">>, <<"Integer">>),
                        type_big_u_int(),
                        64
                    ),
                    type_big_u_int(),
                    Schema
                )
            )
        ),
        ?LAW_HISTORY_IS_THE_LAST_FIVE_COMPLETE_EXCHANGES
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_beam_scalar:remainder(
                lawspec_beam_runtime:helper(
                    <<"length">>,
                    [
                        lawspec_definitions:history_messages(
                            Schema,
                            Symbols,
                            lawspec_definitions:history_times(
                                Schema,
                                Symbols,
                                History,
                                lawspec_beam_schema:validate(
                                    lawspec_beam_scalar:convert(
                                        lawspec_beam_scalar:remainder(
                                            Times,
                                            6,
                                            <<"BigUInt">>,
                                            <<"Integer">>
                                        ),
                                        type_big_u_int(),
                                        64
                                    ),
                                    type_big_u_int(),
                                    Schema
                                )
                            )
                        )
                    ],
                    [<<"List cake.laws.prompt_context::type::Message">>],
                    64
                ),
                2,
                <<"Integer">>,
                <<"Integer">>
            ),
            0,
            ?LAW_HISTORY_IS_THE_LAST_FIVE_COMPLETE_EXCHANGES
        )) andalso
        lawspec_beam_runtime:assert_equal(
            (lawspec_beam_runtime:helper(
                <<"length">>,
                [
                    lawspec_definitions:history_messages(
                        Schema,
                        Symbols,
                        lawspec_definitions:history_times(
                            Schema,
                            Symbols,
                            History,
                            lawspec_beam_schema:validate(
                                lawspec_beam_scalar:convert(
                                    lawspec_beam_scalar:remainder(
                                        Times,
                                        6,
                                        <<"BigUInt">>,
                                        <<"Integer">>
                                    ),
                                    type_big_u_int(),
                                    64
                                ),
                                type_big_u_int(),
                                Schema
                            )
                        )
                    )
                ],
                [<<"List cake.laws.prompt_context::type::Message">>],
                64
            ) =< 10),
            true,
            ?LAW_HISTORY_IS_THE_LAST_FIVE_COMPLETE_EXCHANGES
        )).

