%% |a prompt with context is the context, the recent history, the question| — laws/prompt_context.lawspec:515
%% With at least one chunk, build/4 returns a system message, then the
%%     history as history_messages/1 gives it, then the question as the last
%%     message, a user message, verbatim. The system message is
%%     system_message_with_context/1 of the chunks, each formatted as
%%     format_chunk/1 formats it, in the order given.
%% for all (first :: cake.laws.prompt_context::type::ScoredResult) (rest :: List (cake.laws.prompt_context::type::ScoredResult)) (question :: Text) (history :: List (Text)) => build (indexed (List::Cons(first, rest))) question history = List::Cons(let _lawspecRecordField0 = cake.laws.prompt_context::type::Role::System() in let _lawspecRecordField1 = systemMessageWithContext (entriesOf (indexed (List::Cons(first, rest)))) in cake.laws.prompt_context::type::Message::Message(_lawspecRecordField0, _lawspecRecordField1), Append(historyMessages history, List::Cons(let _lawspecRecordField0 = cake.laws.prompt_context::type::Role::User() in let _lawspecRecordField1 = question in cake.laws.prompt_context::type::Message::Message(_lawspecRecordField0, _lawspecRecordField1), List::Nil()))) end for all
law_a_prompt_with_context_is_the_context_the_recent(
    Schema,
    Symbols,
    [First, Rest, Question, History]
) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:build(
            Schema,
            Symbols,
            lawspec_definitions:indexed(Schema, Symbols, make_cons_4([First, Rest], Schema)),
            Question,
            History
        ),
        make_cons_2(
            [
                lawspec_beam_runtime:bind(
                    make_system([], Schema),
                    fun(RecordField) ->
                        lawspec_beam_runtime:bind(
                            lawspec_definitions:system_message_with_context(
                                Schema,
                                Symbols,
                                lawspec_definitions:entries_of(
                                    Schema,
                                    Symbols,
                                    lawspec_definitions:indexed(
                                        Schema,
                                        Symbols,
                                        make_cons_4([First, Rest], Schema)
                                    )
                                )
                            ),
                            fun(RecordField_2) ->
                                make_message([RecordField, RecordField_2], Schema)
                            end
                        )
                    end
                ),
                lawspec_beam_runtime:helper(
                    <<"append">>,
                    [
                        lawspec_definitions:history_messages(Schema, Symbols, History),
                        make_cons_2(
                            [
                                lawspec_beam_runtime:bind(
                                    make_user([], Schema),
                                    fun(RecordField) ->
                                        lawspec_beam_runtime:bind(
                                            Question,
                                            fun(RecordField_2) ->
                                                make_message([RecordField, RecordField_2], Schema)
                                            end
                                        )
                                    end
                                ),
                                []
                            ],
                            Schema
                        )
                    ],
                    [
                        <<"List cake.laws.prompt_context::type::Message">>,
                        <<"List cake.laws.prompt_context::type::Message">>
                    ],
                    64
                )
            ],
            Schema
        ),
        ?LAW_A_PROMPT_WITH_CONTEXT_IS_THE_CONTEXT_THE_RECENT
    ).

