-define(LAW_A_PROMPT_WITH_NO_CONTEXT_SAYS_SO_THEN_THE_RECENT,
    <<"cake.laws.prompt_context::|a prompt with no context says so, then the recent history, the question|">>
).

%% |a prompt with no context says so, then the recent history, the question| — laws/prompt_context.lawspec:547
%% With no chunks, build/4 returns the no-context system message, then the
%%     history as history_messages/1 gives it, then the question as the last
%%     message, a user message, verbatim. The no-context system message has no
%%     context block.
%% for all (question :: Text) (history :: List (Text)) => build (List::Nil()) question history = List::Cons(let _lawspecRecordField0 = cake.laws.prompt_context::type::Role::System() in let _lawspecRecordField1 = systemMessageNoContext unitValue in cake.laws.prompt_context::type::Message::Message(_lawspecRecordField0, _lawspecRecordField1), Append(historyMessages history, List::Cons(let _lawspecRecordField0 = cake.laws.prompt_context::type::Role::User() in let _lawspecRecordField1 = question in cake.laws.prompt_context::type::Message::Message(_lawspecRecordField0, _lawspecRecordField1), List::Nil()))) and not ((systemMessageNoContext unitValue contains "Context:") = true) end for all
law_a_prompt_with_no_context_says_so_then_the_recent(Schema, Symbols, [Question, History]) ->
    lawspec_beam_runtime:assert_equal(
        (lawspec_beam_scalar:equal(
            lawspec_definitions:build(Schema, Symbols, [], Question, History),
            make_cons_2(
                [
                    lawspec_beam_runtime:bind(
                        make_system([], Schema),
                        fun(RecordField) ->
                            lawspec_beam_runtime:bind(
                                lawspec_definitions:system_message_no_context(
                                    Schema,
                                    Symbols,
                                    ls_unit
                                ),
                                fun(RecordField_2) ->
                                    make_message([RecordField, RecordField_2], Schema)
                                end
                            )
                        end
                    ),
                    lawspec_beam_runtime:helper(
                        <<"append">>,
                        [
                            lawspec_definitions:history_messages(Schema, Symbols, History),
                            make_cons_2(
                                [
                                    lawspec_beam_runtime:bind(
                                        make_user([], Schema),
                                        fun(RecordField) ->
                                            lawspec_beam_runtime:bind(
                                                Question,
                                                fun(RecordField_2) ->
                                                    make_message(
                                                        [RecordField, RecordField_2],
                                                        Schema
                                                    )
                                                end
                                            )
                                        end
                                    ),
                                    []
                                ],
                                Schema
                            )
                        ],
                        [
                            <<"List cake.laws.prompt_context::type::Message">>,
                            <<"List cake.laws.prompt_context::type::Message">>
                        ],
                        64
                    )
                ],
                Schema
            )
        ) andalso
            ((not lawspec_beam_scalar:equal(
                lawspec_beam_runtime:helper(
                    <<"textContains">>,
                    [
                        lawspec_definitions:system_message_no_context(Schema, Symbols, ls_unit),
                        <<"Context:">>
                    ],
                    [<<"Text">>, <<"Text">>],
                    64
                ),
                true
            )) andalso true)),
        true,
        ?LAW_A_PROMPT_WITH_NO_CONTEXT_SAYS_SO_THEN_THE_RECENT
    ).

