-define(LAW_THE_CONTEXT_BLOCK_LISTS_THE_FORMATTED_CHUNKS_IN,
    <<"cake.laws.prompt_context::|the context block lists the formatted chunks in order|">>
).

%% |the context block lists the formatted chunks in order| — laws/prompt_context.lawspec:573
%% system_message_with_context/1 ends with a context block: the line
%%     `Context:`, then the formatted chunks in the order given, separated by
%%     lines of three hyphens, then a newline.
%% for all (formatted :: List (Text)) => (systemMessageWithContext formatted ends with Append(Append("Context:\n", Join("\n---\n", formatted)), "\n")) = true end for all
law_the_context_block_lists_the_formatted_chunks_in(Schema, Symbols, [Formatted]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_runtime:helper(
            <<"endsWith">>,
            [
                lawspec_definitions:system_message_with_context(Schema, Symbols, Formatted),
                lawspec_beam_runtime:helper(
                    <<"append">>,
                    [
                        lawspec_beam_runtime:helper(
                            <<"append">>,
                            [
                                <<"Context:\n">>,
                                lawspec_beam_runtime:helper(
                                    <<"join">>,
                                    [<<"\n---\n">>, Formatted],
                                    [<<"Text">>, <<"List Text">>],
                                    64
                                )
                            ],
                            [<<"Text">>, <<"Text">>],
                            64
                        ),
                        <<"\n">>
                    ],
