finite_literal_64(_Symbols) -> [<<"a\n\t\"\\$\x{0}z">>, <<"a\n\t\"\\$\x{0}z">>].

finite_literal_65(_Symbols) -> [<<"é"/utf8>>].

finite_literal_66(_Symbols) -> [<<"é"/utf8>>, <<"é"/utf8>>].

finite_literal_67(_Symbols) -> [<<"\x{0}aλ😀\x{10ffff}"/utf8>>].

finite_literal_68(_Symbols) -> [<<"\x{0}aλ😀\x{10ffff}"/utf8>>, <<"\x{0}aλ😀\x{10ffff}"/utf8>>].

type_big_u_int() -> {<<"BigUInt">>, []}.

type_bool() -> {<<"Bool">>, []}.

type_integer() -> {<<"Integer">>, []}.

type_list_text() -> {<<"List">>, [{<<"Text">>, []}]}.

type_list_message() -> {<<"List">>, [{<<"cake.laws.prompt_context::type::Message">>, []}]}.

