type_list_scored_result() ->
    {<<"List">>, [{<<"cake.laws.prompt_context::type::ScoredResult">>, []}]}.

type_maybe_big_u_int() -> {<<"Maybe">>, [{<<"BigUInt">>, []}]}.

type_maybe_integer() -> {<<"Maybe">>, [{<<"Integer">>, []}]}.

