make_cons(Fields, Schema) ->
    lawspec_beam_schema:construct(<<"List::Cons">>, Fields, type_list_text(), Schema).

make_nil(Fields, Schema) ->
    lawspec_beam_schema:construct(<<"List::Nil">>, Fields, type_list_text(), Schema).

